import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:supabase_flutter/supabase_flutter.dart';
class CrmContact { CrmContact.fromJson(Map<String,dynamic> j):id='${j['id']}',name='${j['full_name']??'Unnamed contact'}',phone='${j['whatsapp_number']??j['phone']??''}',email='${j['email']??''}',company='${j['company_name']??''}',status='${j['lifecycle_status']??''}',notes='${j['notes']??''}'; final String id,name,phone,email,company,status,notes; }
class WhatsAppAgentState { WhatsAppAgentState.fromJson(Map<String,dynamic> j):id='${j['id']}',status='${j['status']??'paused'}'; final String id,status; bool get active=>status=='active'; }
class InboxConversation { InboxConversation.fromJson(Map<String,dynamic> j):id='${j['id']}',contactId='${j['contact_id']??''}',status='${j['status']??'open'}',channel='${j['channel_key']??'whatsapp'}',lastActivity='${j['last_activity_at']??''}'; final String id,contactId,status,channel,lastActivity; }
class UnifiedMessage { UnifiedMessage.fromJson(Map<String,dynamic> j):id='${j['id']}',content='${j['content']??''}',direction='${j['direction']??''}',status='${j['delivery_status']??''}',agent=j['agent_generated']==true,human=j['human_generated']==true,created='${j['created_at']??''}'; final String id,content,direction,status,created; final bool agent,human; }
class CrmInboxRepository { CrmInboxRepository(this.baseUrl,this.client); final String baseUrl; final SupabaseClient client; Future<Map<String,String>> _h() async { final t=client.auth.currentSession?.accessToken; if(t==null) throw Exception('Sign in required.'); return {'Authorization':'Bearer $t','Content-Type':'application/json'}; } Future<dynamic> _get(String p) async { final r=await http.get(Uri.parse('$baseUrl$p'),headers:await _h()); if(r.statusCode>=400) throw Exception('Request failed.'); return jsonDecode(r.body); } Future<dynamic> _post(String p,Map<String,dynamic> b) async { final r=await http.post(Uri.parse('$baseUrl$p'),headers:await _h(),body:jsonEncode(b)); if(r.statusCode>=400) throw Exception('Request failed.'); return jsonDecode(r.body); } Future<dynamic> _patch(String p,Map<String,dynamic> b) async { final r=await http.patch(Uri.parse('$baseUrl$p'),headers:await _h(),body:jsonEncode(b)); if(r.statusCode>=400) throw Exception('Request failed.'); return jsonDecode(r.body); } Future<List<CrmContact>> contacts() async=>(await _get('/api/v1/crm/contacts'))['contacts'].map<CrmContact>((x)=>CrmContact.fromJson(Map<String,dynamic>.from(x))).toList(); Future<CrmContact> contact(String id) async=>CrmContact.fromJson(Map<String,dynamic>.from((await _get('/api/v1/crm/contacts/$id'))['contact'])); Future<CrmContact> updateContact(String id,Map<String,dynamic> values) async=>CrmContact.fromJson(Map<String,dynamic>.from((await _patch('/api/v1/crm/contacts/$id',values))['contact'])); Future<List<InboxConversation>> conversations() async=>(await _get('/api/v1/inbox/conversations'))['conversations'].map<InboxConversation>((x)=>InboxConversation.fromJson(Map<String,dynamic>.from(x))).toList(); Future<List<UnifiedMessage>> messages(String id) async=>(await _get('/api/v1/inbox/conversations/$id/messages'))['messages'].map<UnifiedMessage>((x)=>UnifiedMessage.fromJson(Map<String,dynamic>.from(x))).toList(); Future<void> send(String id,String text) async { await _post('/api/v1/inbox/conversations/$id/messages',{'text':text}); } Future<void> takeover(String id) async { await _post('/api/v1/inbox/conversations/$id/takeover',{}); } Future<void> handback(String id) async { await _post('/api/v1/inbox/conversations/$id/handback',{}); } Future<Map<String,dynamic>?> integration() async=>(await _get('/api/v1/integrations/whatsapp'))['integration']; Future<WhatsAppAgentState> agent() async=>WhatsAppAgentState.fromJson(Map<String,dynamic>.from((await _get('/api/v1/agents/whatsapp'))['agent'])); Future<WhatsAppAgentState> setAgentStatus(String status) async=>WhatsAppAgentState.fromJson(Map<String,dynamic>.from((await _post('/api/v1/agents/whatsapp/status',{'status':status}))['agent'])); }
